/* @lc app=leetcode id=2060 lang=kotlin */ class Solution { fun possiblyEquals(s1: String, s2: String): Boolean = java.util.HashSet<Triple<Int, Int, Int>>().let { vis -> kotlin.DeepRecursiveFunction<Triple<Int, Int, Int>, Boolean> { (i, j, d) -> if (i == s1.length && j == s2.length && d == 0) true else if (!vis.add(Triple(i, j, d))) false else (if (i < s1.length && s1[i].isDigit()) (i until minOf(i + 3, s1.length)).takeWhile { s1[it].isDigit() }.any { k -> callRecursive(Triple(k + 1, j, d - s1.substring(i, k + 1).toInt())) } else if (j < s2.length && s2[j].isDigit()) (j until minOf(j + 3, s2.length)).takeWhile { s2[it].isDigit() }.any { k -> callRecursive(Triple(i, k + 1, d + s2.substring(j, k + 1).toInt())) } else if (d > 0) (i < s1.length && !s1[i].isDigit() && callRecursive(Triple(i + 1, j, d - 1))) else if (d < 0) (j < s2.length && !s2[j].isDigit() && callRecursive(Triple(i, j + 1, d + 1))) else (i < s1.length && j < s2.length && s1[i] == s2[j] && callRecursive(Triple(i + 1, j + 1, 0)))) }.invoke(Triple(0, 0, 0)) } }